function clickCheckbox(e){e.currentTarget.querySelector('input[type="checkbox"]').click()}function chooseAll(e,t,c){var n=e.currentTarget.checked;const r=e.currentTarget.closest(t);const o=r.querySelector(".group").querySelectorAll(c);if(n){o.forEach((e=>{if(!e.checked){e.checked=true;e.dispatchEvent(new Event("change"))}}))}else{o.forEach((e=>{e.checked=false;e.dispatchEvent(new Event("change"))}))}}function setupCartTable(e){const t=document.querySelector(e);const c=t.querySelector("#check-all");if(c)c.addEventListener("change",(e=>{chooseAll(e,".cart-form",".p-check")}));const n=t.querySelectorAll("tbody tr");n.forEach((e=>{const t=e.querySelector(".temp-money");const r=e.querySelector(".price-unit");const o=e.querySelector(".qty-input");if(t&&r)t.value=parseFloat(r.innerText.replace(/[₫,.]/g,"").trim())*parseInt(o.value);const a=e.querySelector(".btn-plus");const l=e.querySelector(".btn-minus");if(a)a.addEventListener("click",(e=>{plusProduct(e)}));if(l)l.addEventListener("click",(e=>{minusProduct(e)}));const u=e.querySelector(".p-check");if(u)u.addEventListener("change",(e=>{checkProduct(e);updateCheckAll(n,c)}));if(t)t.addEventListener("change",(e=>{catchTempMoney(e)}))}))}function plusProduct(e){const t=e.currentTarget.closest("tr");const c=t.querySelector(".qty-input");let n;updateQtyAjax(t.getAttribute("data-value"),"plus").then((e=>{n=e;const r=t.querySelector(".temp-money");c.value=n;let o=t.querySelector(".price-unit").innerText.replace(/[₫,.]/g,"").trim();r.value=parseFloat(o)*n;r.dispatchEvent(new Event("change"))})).catch((e=>{console.error("Có lỗi khi cập nhật số lượng:",e)}))}function minusProduct(e){const t=e.currentTarget.closest("tr");const c=t.querySelector(".qty-input");let n;updateQtyAjax(t.getAttribute("data-value"),"minus").then((e=>{n=e;const r=t.querySelector(".temp-money");if(n>0){c.value=n;let e=t.querySelector(".price-unit").innerText.replace(/[₫,.]/g,"").trim();r.value=parseFloat(e)*n}else{t.style.display="none";const e=document.querySelector(".num-of-cart");let c=parseInt(e.innerText)-1;e.innerText=c;r.value=0}r.dispatchEvent(new Event("change"))})).catch((e=>{console.error("Có lỗi khi cập nhật số lượng:",e)}))}function updateQtyAjax(e,t,c){return new Promise(((c,n)=>{$.ajax({url:"cart?a=updateQty",type:"GET",dataType:"text",data:{cartID:e,operation:t},success:function(e){c(parseInt(e))},error:function(e,t,c){n(c)}})}))}function checkProduct(e){const t=e.currentTarget.closest("tr");const c=t.querySelector(".temp-money");const n=document.querySelector("#totalMoney");const r=document.querySelector("#totalProduct");console.log(r);if(e.currentTarget.checked){n.innerText=(parseFloat(n.innerText.replace(/[₫,.]/g,"").trim().replace(",","."))+parseFloat(c.value)).toLocaleString("vi-VN")+" ₫";r.innerText=parseInt(r.innerText)+1}else if(!e.currentTarget.checked){n.innerText=(parseFloat(n.innerText.replace(/[₫,.]/g,"").trim().replace(",","."))-parseFloat(c.value)).toLocaleString("vi-VN")+" ₫";r.innerText=parseInt(r.innerText)-1}}function updateCheckAll(e,t){let c=true;for(let t=0;t<e.length;t++){if(!e[t].querySelector(".p-check").checked){c=false;break}}t.checked=c}function catchTempMoney(e){const t=e.currentTarget.closest(".group");const c=t.querySelectorAll("tr");let n=0;c.forEach((e=>{if(e.querySelector(".p-check").checked){let t=parseFloat(e.querySelector(".temp-money").value);n+=t}}));const r=document.querySelector("#totalMoney");r.innerText=n.toLocaleString("vi-VN")+" ₫"}function remove(e){const t=document.querySelector("tr#cartItem"+e);const c=t.querySelector(".temp-money");c.value=0;c.dispatchEvent(new Event("change"));$.ajax({url:"cart?a=remove",type:"GET",data:{cartID:e},success:function(t){document.querySelector('tr[data-value="'+e+'"]').style.display="none";console.log(t);console.log(document.querySelector("#cart-response"));document.querySelector("#cart-response").innerHTML=t},error:function(e,t,c){}})}document.addEventListener("DOMContentLoaded",(function(){setupCartTable("#cartTable");document.getElementById("cartForm").addEventListener("submit",(function(e){e.preventDefault();const t=[];document.querySelectorAll('input[name="cart-check"]:checked').forEach((e=>{t.push(e.value)}));if(t.length>0){this.submit()}else{showInfoToast2("Vui lòng chọn ít nhất một mục!","none")}}))}));